(function(){const WALINE_CONTAINER_SELECTOR='#waline';const WALINE_MODULE_URL='https://help-site.oss-cn-hangzhou.aliyuncs.com/js/waline.js';const CONTAINER_RETRY_DELAY=100;const CONTAINER_MAX_RETRY_COUNT=20;const MATERIAL_OBSERVER_POLL_INTERVAL=100;const MATERIAL_OBSERVER_MAX_WAIT_COUNT=100;const DOM_OBSERVER_DEBOUNCE=80;const MAIN_EDITOR_CLASS='site-comment-main';const GUEST_EDITOR_CLASS='site-comment-guest';const EXPANDED_EDITOR_CLASS='site-comment-expanded';const GUEST_PLACEHOLDER='点击登录后参与评论';const GUEST_LABEL='登录后参与评论';const EDITOR_EASE='cubic-bezier(0.22, 1, 0.36, 1)';const EDITOR_RESIZE_DURATION=240;const EDITOR_FADE_DURATION=200;const editorAnimations=new WeakMap();const CLIP_OVERFLOW=window.CSS&&CSS.supports('overflow','clip')?'clip':'hidden';let walineModulePromise=null;let walineInstance=null;let walineContainer=null;let initSequence=0;let containerRetryTimer=null;let pageChangeSubscribed=false;let observerWaitTimer=null;let domObserver=null;let mountScheduleTimer=null;let editorInteractionsBound=false;const locale={placeholder:'写下你的评论…',oldest:'最早评论',latest:'最新评论',hottest:'点赞量最多',logout:'退出登录',like:'点赞',cancelLike:'取消点赞'};function syncCommentActionLabels(){const container=document.querySelector(WALINE_CONTAINER_SELECTOR);if(!container){return;}
container.querySelectorAll('.wl-comment-actions button').forEach((button)=>{let label=button.title;if(button.classList.contains('wl-edit')){label='编辑评论';}else if(button.classList.contains('wl-delete')){label='删除评论';}
if(!label){return;}
if(button.title!==label){button.title=label;}
if(button.getAttribute('aria-label')!==label){button.setAttribute('aria-label',label);}});}
function getMainEditor(){const container=document.querySelector(WALINE_CONTAINER_SELECTOR);if(!container){return null;}
return Array.from(container.querySelectorAll('.wl-comment')).find((editor)=>!editor.closest('.wl-reply-wrapper, .wl-edit-wrapper'))||null;}
function isEditorEmpty(editor){const textarea=editor.querySelector('.wl-editor');return!textarea||textarea.value.trim()==='';}
function setEditorAttribute(element,name,value){if(element.getAttribute(name)!==value){element.setAttribute(name,value);}}
function syncMainEditor(){const editor=getMainEditor();if(!editor){return;}
const textarea=editor.querySelector('.wl-editor');const isGuest=!editor.querySelector('.wl-login-info');editor.classList.add(MAIN_EDITOR_CLASS);editor.classList.toggle(GUEST_EDITOR_CLASS,isGuest);if(isGuest){editor.classList.remove(EXPANDED_EDITOR_CLASS);setEditorAttribute(editor,'role','button');setEditorAttribute(editor,'tabindex','0');setEditorAttribute(editor,'aria-label',GUEST_LABEL);if(textarea){textarea.disabled=true;setEditorAttribute(textarea,'placeholder',GUEST_PLACEHOLDER);}
return;}
['role','tabindex','aria-label'].forEach((name)=>editor.removeAttribute(name));if(textarea&&textarea.disabled){textarea.disabled=false;textarea.placeholder=locale.placeholder;}
if(!isEditorEmpty(editor)){editor.classList.add(EXPANDED_EDITOR_CLASS);}}
function triggerLogin(editor){const loginButton=editor.querySelector('.wl-footer .wl-btn:not(.primary)');if(loginButton){loginButton.click();}}
function collapseIfEmpty(editor){if(editor.classList.contains(EXPANDED_EDITOR_CLASS)&&isEditorEmpty(editor)){setExpanded(editor,false);}}
function setExpanded(editor,expanded){if(editor.classList.contains(EXPANDED_EDITOR_CLASS)===expanded){return;}
const fromHeight=editor.getBoundingClientRect().height;(editorAnimations.get(editor)||[]).forEach((animation)=>animation.cancel());editor.classList.toggle(EXPANDED_EDITOR_CLASS,expanded);if(typeof editor.animate!=='function'){return;}
const toHeight=editor.getBoundingClientRect().height;const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const animations=[];if(!reduceMotion&&fromHeight!==toHeight){animations.push(editor.animate([{height:`${fromHeight}px`,overflow:CLIP_OVERFLOW},{height:`${toHeight}px`,overflow:CLIP_OVERFLOW}],{duration:EDITOR_RESIZE_DURATION,easing:EDITOR_EASE}));}
if(expanded){editor.querySelectorAll('.wl-footer, .wl-logout-btn').forEach((element)=>{animations.push(element.animate([{opacity:0},{opacity:1}],{duration:EDITOR_FADE_DURATION,easing:EDITOR_EASE}));});}
editorAnimations.set(editor,animations);}
function bindEditorInteractions(){if(editorInteractionsBound){return;}
editorInteractionsBound=true;document.addEventListener('pointerdown',(event)=>{const editor=getMainEditor();if(editor&&!editor.contains(event.target)){collapseIfEmpty(editor);}});document.addEventListener('focusin',(event)=>{const editor=getMainEditor();if(!editor){return;}
if(!editor.contains(event.target)){collapseIfEmpty(editor);}else if(!editor.classList.contains(GUEST_EDITOR_CLASS)){setExpanded(editor,true);}});document.addEventListener('click',(event)=>{const editor=event.target.closest(`.${MAIN_EDITOR_CLASS}`);if(!editor){return;}
if(editor.classList.contains(GUEST_EDITOR_CLASS)){if(!event.target.closest('.wl-footer')){event.preventDefault();triggerLogin(editor);}
return;}
if(!editor.classList.contains(EXPANDED_EDITOR_CLASS)&&!event.target.closest('a, button')){setExpanded(editor,true);const textarea=editor.querySelector('.wl-editor');if(textarea){textarea.focus({preventScroll:true});}}});document.addEventListener('keydown',(event)=>{const editor=event.target;if(editor instanceof Element&&editor.classList.contains(MAIN_EDITOR_CLASS)&&editor.classList.contains(GUEST_EDITOR_CLASS)&&(event.key==='Enter'||event.key===' ')){event.preventDefault();triggerLogin(editor);}});}
function loadWalineModule(){if(!walineModulePromise){walineModulePromise=import(WALINE_MODULE_URL).catch((error)=>{walineModulePromise=null;throw error;});}
return walineModulePromise;}
function clearWalineContainer(){if(walineContainer){walineContainer.textContent='';}}
function destroyWalineInstance(){if(walineInstance&&typeof walineInstance.destroy==='function'){walineInstance.destroy();}
walineInstance=null;clearWalineContainer();}
function clearContainerRetryTimer(){if(containerRetryTimer!==null){window.clearTimeout(containerRetryTimer);containerRetryTimer=null;}}
function scheduleRetry(retryCount){clearContainerRetryTimer();containerRetryTimer=window.setTimeout(()=>{void mountWaline(retryCount+1);},CONTAINER_RETRY_DELAY);}
function afterNextPaint(callback){window.requestAnimationFrame(()=>{window.requestAnimationFrame(callback);});}
function clearMountScheduleTimer(){if(mountScheduleTimer!==null){window.clearTimeout(mountScheduleTimer);mountScheduleTimer=null;}}
function scheduleMountWaline(){clearMountScheduleTimer();mountScheduleTimer=window.setTimeout(()=>{mountScheduleTimer=null;afterNextPaint(()=>{void mountWaline();});},DOM_OBSERVER_DEBOUNCE);}
function shouldAttemptMount(){const container=document.querySelector(WALINE_CONTAINER_SELECTOR);if(!container){return walineContainer!==null||walineInstance!==null;}
return(container!==walineContainer||walineInstance===null||container.childElementCount===0);}
async function mountWaline(retryCount=0){if(walineContainer&&!walineContainer.isConnected){walineContainer=null;walineInstance=null;}
const container=document.querySelector(WALINE_CONTAINER_SELECTOR);if(!container){if(retryCount<CONTAINER_MAX_RETRY_COUNT){scheduleRetry(retryCount);return;}
clearContainerRetryTimer();destroyWalineInstance();walineContainer=null;return;}
clearContainerRetryTimer();if(container===walineContainer&&walineInstance&&container.childElementCount>0){return;}
const currentSequence=++initSequence;destroyWalineInstance();walineContainer=container;try{const{init}=await loadWalineModule();if(currentSequence!==initSequence||walineContainer!==container){return;}
container.textContent='';walineInstance=init({el:container,path:window.location.pathname,serverURL:'https://waline-comment.netlify.app/.netlify/functions/comment',dark:'html[data-force-dark-theme]:not([data-force-dark-theme="off"])',emoji:['https://unpkg.com/@waline/emojis@1.2.0/bilibili','https://unpkg.com/@waline/emojis@1.2.0/bmoji','https://unpkg.com/@waline/emojis@1.2.0/qq','https://unpkg.com/@waline/emojis@1.2.0/tw-emoji','https://unpkg.com/@waline/emojis@1.2.0/weibo'],lang:'zh-CN',comment:true,search:false,meta:[],requiredMeta:[],login:'force',pageSize:3,noCopyright:true,locale});}catch(error){if(currentSequence!==initSequence){return;}
console.error('[waline] 初始化失败',error);}}
function clearObserverWaitTimer(){if(observerWaitTimer!==null){window.clearInterval(observerWaitTimer);observerWaitTimer=null;}}
function trySubscribeToMaterialDocument(callback){if(pageChangeSubscribed){return true;}
if(typeof document$==='undefined'||typeof document$.subscribe!=='function'){return false;}
document$.subscribe(()=>{callback();});pageChangeSubscribed=true;clearObserverWaitTimer();return true;}
function subscribeToPageChanges(callback){const runNow=()=>{afterNextPaint(()=>{callback();});};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',runNow,{once:true});}else{runNow();}
if(trySubscribeToMaterialDocument(callback)){return;}
let waitCount=0;clearObserverWaitTimer();observerWaitTimer=window.setInterval(()=>{waitCount+=1;if(trySubscribeToMaterialDocument(callback)){return;}
if(waitCount>=MATERIAL_OBSERVER_MAX_WAIT_COUNT){clearObserverWaitTimer();}},MATERIAL_OBSERVER_POLL_INTERVAL);}
function observeDomChanges(){if(domObserver||typeof MutationObserver==='undefined'){return;}
domObserver=new MutationObserver(()=>{syncCommentActionLabels();syncMainEditor();if(shouldAttemptMount()){scheduleMountWaline();}});domObserver.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['title']});}
subscribeToPageChanges(()=>{scheduleMountWaline();observeDomChanges();bindEditorInteractions();});})();